package dev.wowforever.importer.acquisition;
import static org.assertj.core.api.Assertions.*;
import java.util.*;import java.util.concurrent.CancellationException;import org.junit.jupiter.api.Test;
class PinnedItemSparseOverlayMaterializerTest {
 DecodedItemSparseSnapshot.Event event(long id,int region,int push,HotfixSnapshotReader.Status status,Map<String,Object> row){return new DecodedItemSparseSnapshot.Event(push,new HotfixSnapshotReader.Entry(push,region,push,1,ItemSparseHotfixDecoder.TABLE_HASH,id,0,0,status),row);}
 DecodedItemSparseSnapshot ledger(DecodedItemSparseSnapshot.Event...events){return new DecodedItemSparseSnapshot(new RaidbotsHotfixMaterializer.Pin("wow_classic_beta","1.60.1.70450","enUS",PinnedItemSparseOverlayMaterializer.SNAPSHOT_SHA),"RAIDBOTS_HOTFIX",PinnedItemSparseOverlayMaterializer.SNAPSHOT_SHA,PinnedItemSparseDefinition.COMMIT,PinnedItemSparseDefinition.SHA256,PinnedItemSparseDefinition.LAYOUT,List.of("ID","Name"),List.of(events));}
 DecodedItemSparseSnapshot.Event valid(long id,int push,String name){return event(id,70,push,HotfixSnapshotReader.Status.VALID,Map.of("ID",id,"Name",name));}
 @Test void equalDuplicateFactsCollapseWithoutChoosingPushOrder()throws Exception{var p=PinnedItemSparseOverlayMaterializer.resolve(ledger(valid(5,17000000,"Five"),valid(5,100,"Five")),Set.of(1L),()->false);assertThat(p.rows()).hasSize(1).containsKey(5L);assertThat(p.excluded()).isEmpty();}
 @Test void differentDuplicateFactsAreAmbiguousEvenWhenPushOrderSeemsClear(){assertThatThrownBy(()->PinnedItemSparseOverlayMaterializer.resolve(ledger(valid(5,1,"Old"),valid(5,2,"New")),Set.of(),()->false)).hasMessageContaining("Ambiguous");}
 @Test void invalidatedIdsAreRetainedAsUnknownExclusions()throws Exception{var p=PinnedItemSparseOverlayMaterializer.resolve(ledger(valid(5,1,"Five"),event(8,70,2,HotfixSnapshotReader.Status.INVALIDATED,Map.of())),Set.of(1L),()->false);assertThat(p.rows()).containsOnlyKeys(5L);assertThat(p.excluded()).containsExactly(8L);}
 @Test void invalidatedOverlapWithAnyValidRowFailsRatherThanInventingRetraction(){assertThatThrownBy(()->PinnedItemSparseOverlayMaterializer.resolve(ledger(valid(5,1,"Five"),event(5,70,2,HotfixSnapshotReader.Status.INVALIDATED,Map.of())),Set.of(),()->false)).hasMessageContaining("overlap native facts");}
 @Test void invalidatedOverlapWithBaseSparseFails(){assertThatThrownBy(()->PinnedItemSparseOverlayMaterializer.resolve(ledger(event(8,70,1,HotfixSnapshotReader.Status.INVALIDATED,Map.of())),Set.of(8L),()->false)).hasMessageContaining("overlap native facts");}
 @Test void removalAndNonPublicEventsFailClosed(){for(var status:List.of(HotfixSnapshotReader.Status.REMOVED,HotfixSnapshotReader.Status.NOT_PUBLIC))assertThatThrownBy(()->PinnedItemSparseOverlayMaterializer.resolve(ledger(event(8,70,1,status,Map.of())),Set.of(),()->false)).hasMessageContaining("unsupported");}
 @Test void regionIsOpaqueExactPinAndMixedOrForeignRegionFails(){assertThatThrownBy(()->PinnedItemSparseOverlayMaterializer.resolve(ledger(valid(5,1,"Five"),event(6,1,2,HotfixSnapshotReader.Status.VALID,Map.of("ID",6L))),Set.of(),()->false)).hasMessageContaining("opaque hotfix region");}
 @Test void cancellationStopsBeforeReturningAnyProjection(){assertThatThrownBy(()->PinnedItemSparseOverlayMaterializer.resolve(ledger(valid(5,1,"Five")),Set.of(),()->true)).isInstanceOf(CancellationException.class);}
 @Test void permissionCannotBeInheritedFromOtherSources(){assertThatThrownBy(()->new PinnedItemSparseOverlayMaterializer().materialize(RaidbotsHotfixMaterializer.Permission.DENIED,null,null,null,null,null,()->false,p->{})).hasMessageContaining("Independent Raidbots");}
 @Test void archiveAdapterCannotReturnUnboundedBytes(){var input=new PinnedItemSparseOverlayMaterializer.Input(){public Set<String> paths(){return Set.of();}public byte[] read(String p,long max){return new byte[(int)max+1];}};assertThatThrownBy(()->new PinnedItemSparseOverlayMaterializer().validate(input,()->false)).hasMessageContaining("oversized");}
 @Test void archiveAdapterMalformedMetadataCannotBecomeMaterializedInput(){var input=new PinnedItemSparseOverlayMaterializer.Input(){public Set<String> paths(){return Set.of();}public byte[] read(String p,long max){return "not JSON".getBytes(java.nio.charset.StandardCharsets.UTF_8);}};assertThatThrownBy(()->new PinnedItemSparseOverlayMaterializer().validate(input,()->false)).hasMessageContaining("Invalid JSON");}
 @Test void returnedExclusionsAndRowsCannotBeEdited()throws Exception{var projection=PinnedItemSparseOverlayMaterializer.resolve(ledger(valid(5,1,"Five"),event(8,70,2,HotfixSnapshotReader.Status.INVALIDATED,Map.of())),Set.of(),()->false);assertThatThrownBy(()->projection.rows().clear()).isInstanceOf(UnsupportedOperationException.class);assertThatThrownBy(()->projection.excluded().clear()).isInstanceOf(UnsupportedOperationException.class);var result=new PinnedItemSparseOverlayMaterializer.Validation("a",projection.excluded(),projection.rows().keySet(),1);assertThatThrownBy(()->result.overlayIds().clear()).isInstanceOf(UnsupportedOperationException.class);}
 @Test void byteAndPathReadersShareStatusAndMalformedFramingChecks(@org.junit.jupiter.api.io.TempDir java.nio.file.Path temporary)throws Exception{
  var reader=new HotfixSnapshotReader();byte[] bytes=RaidbotsHotfixMaterializerTest.snapshot(70450,1,2,3,4);var file=temporary.resolve("cache.bin");java.nio.file.Files.write(file,bytes);
  assertThat(reader.read(bytes,70450,4096,100,()->false)).isEqualTo(reader.read(file,70450,4096,100,()->false));
  byte[] invalid=Arrays.copyOf(bytes,50);java.nio.file.Files.write(file,invalid);
  assertThatThrownBy(()->reader.read(invalid,70450,4096,100,()->false)).hasMessageContaining("Truncated");assertThatThrownBy(()->reader.read(file,70450,4096,100,()->false)).hasMessageContaining("Truncated");
 }

}
